import numpy as np
import pandas as pd
from pandas import Period, PeriodIndex, Series

left = PeriodIndex([Period(ordinal=-(2**62), freq="D")])
right = PeriodIndex([Period(ordinal=2**62, freq="D")])

def extract(res):
    if hasattr(res, "n"):
        return int(res.n)
    if hasattr(res, "iloc"):
        return int(res.iloc[0].n)
    return int(res[0].n)

def count(fn):
    try:
        return extract(fn())
    except Exception:
        return -1

probe("pi_sub_pi_count", count(lambda: left - right))
probe("pi_sub_period_count", count(lambda: left - Period(ordinal=2**62, freq="D")))
probe("series_sub_series_count", count(lambda: Series(left) - Series(right)))
probe("data_sub_data_count", count(lambda: left._data - right._data))
probe("scalar_sub_count", count(lambda: left[0] - right[0]))

def raises(fn):
    try:
        fn()
        return 0
    except Exception:
        return 1

big = PeriodIndex([Period(ordinal=2**62, freq="D")])
small = PeriodIndex([Period(ordinal=-(2**62), freq="D")])
probe("genuine_overflow_raises", raises(lambda: big - small))

pi = PeriodIndex([Period(ordinal=-(2**63) + 1, freq="D")])
probe("int_lands_on_sentinel_raises", raises(lambda: pi - 1))

ln = PeriodIndex([Period(ordinal=-(2**62), freq="D"), pd.NaT])
rn = PeriodIndex([pd.NaT, Period(ordinal=2**62, freq="D")])
try:
    res = ln - rn
    first = res.iloc[0] if hasattr(res, "iloc") else res[0]
    probe("nat_propagates", 1 if pd.isna(first) else 0)
except Exception:
    probe("nat_propagates", -1)

